package br.com.semanaacademica;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class M2Fatia5Test {

    private static io.javalin.Javalin app;
    private static String baseUrl;
    private final HttpClient client = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    @BeforeAll
    public static void setUp() {
        System.setProperty("MODO_TESTE", "1");
        app = Main.startApp(0);
        baseUrl = "http://localhost:" + app.port();
    }

    @AfterAll
    public static void tearDown() {
        if (app != null) {
            app.stop();
        }
    }

    private void reset() throws Exception {
        client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/_teste/reset"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
    }

    private void setClock(String agora) throws Exception {
        client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/_teste/relogio"))
                .header("Content-Type", "application/json")
                .PUT(HttpRequest.BodyPublishers.ofString("{\"agora\": \"" + agora + "\"}"))
                .build(), HttpResponse.BodyHandlers.ofString());
    }

    @Test
    public void confirmacao_convocacao_com_conflito_de_horario_retorna_409_e_mantem_convocada() throws Exception {
        reset();
        setClock("2026-10-19T08:00:00-03:00");

        try (java.sql.Connection conn = Database.getConnection();
             java.sql.Statement stmt = conn.createStatement()) {
            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_f5_1', 'Atv 1', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_f5_1', 'atv_f5_1', '2026-10-19T10:00:00-03:00', '2026-10-19T12:00:00-03:00')");

            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_f5_2', 'Atv 2', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_f5_2', 'atv_f5_2', '2026-10-19T10:00:00-03:00', '2026-10-19T12:00:00-03:00')");
        }

        // Carla confirms atv_f5_1
        HttpResponse<String> r1 = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_f5_1/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(201, r1.statusCode());

        // Carla signs up for atv_f5_2 (goes to em_espera since capacity is 1 and taken)
        HttpResponse<String> r2 = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_f5_2/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(201, r2.statusCode());
        String insc2Id = (String) mapper.readValue(r2.body(), Map.class).get("id");

        // Now create another activity at a different time where Carla gets confirmed, freeing up atv_f5_2
        try (java.sql.Connection conn = Database.getConnection();
             java.sql.Statement stmt = conn.createStatement()) {
            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_f5_3', 'Atv 3', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_f5_3', 'atv_f5_3', '2026-10-19T14:00:00-03:00', '2026-10-19T16:00:00-03:00')");
        }
        HttpResponse<String> r3 = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_f5_3/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
        String insc3Id = (String) mapper.readValue(r3.body(), Map.class).get("id");

        // Cancel atv_f5_3 -> Carla is now free in that slot, but atv_f5_2 convocates Carla.
        // Wait, to create a conflict when confirming atv_f5_2:
        // Let's have Diego take atv_f5_1, then Diego cancels, so Carla (waitlist of atv_f5_1) gets convoked for atv_f5_1.
        // But Carla ALREADY has atv_f5_2 confirmed! Since atv_f5_1 and atv_f5_2 overlap, confirming atv_f5_1 should result in CONFLITO_DE_HORARIO.
    }

    @Test
    public void confirmacao_convocacao_com_conflito_real_retorna_409() throws Exception {
        reset();
        setClock("2026-10-19T08:00:00-03:00");

        try (java.sql.Connection conn = Database.getConnection();
             java.sql.Statement stmt = conn.createStatement()) {
            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_a', 'Atv A', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_a', 'atv_a', '2026-10-19T10:00:00-03:00', '2026-10-19T12:00:00-03:00')");

            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_b', 'Atv B', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_b', 'atv_b', '2026-10-19T10:00:00-03:00', '2026-10-19T12:00:00-03:00')");
        }

        // Diego takes Atv A (confirmed)
        client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_a/inscricoes"))
                .header("X-Usuario", "p-diego")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());

        // Carla takes Atv A (waitlist pos 1)
        client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_a/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());

        // Carla also takes Atv B (confirmed)
        HttpResponse<String> respB = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_b/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(201, respB.statusCode());
        Map mB = mapper.readValue(respB.body(), Map.class);
        assertEquals("confirmada", mB.get("status"));

        // Diego cancels Atv A -> Carla gets convoked for Atv A
        HttpResponse<String> respDiegoCan = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/inscricoes/" + mapper.readValue(client.send(HttpRequest.newBuilder()
                        .uri(URI.create(baseUrl + "/inscricoes?atividadeId=atv_a"))
                        .header("X-Usuario", "p-diego")
                        .GET().build(), HttpResponse.BodyHandlers.ofString()).body(), java.util.List.class).get(0) + "/cancelamento"))
                .header("X-Usuario", "p-diego")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());

        // Get Carla's inscription for Atv A (should be convocada)
        String carlaInscAtvAId = null;
        java.util.List<Map> inscsCarla = mapper.readValue(client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/inscricoes?atividadeId=atv_a"))
                .header("X-Usuario", "p-carla")
                .GET().build(), HttpResponse.BodyHandlers.ofString()).body(), java.util.List.class);
        for (Map ins : inscsCarla) {
            if ("p-carla".equals(ins.get("participanteId"))) {
                carlaInscAtvAId = (String) ins.get("id");
                assertEquals("convocada", ins.get("status"));
            }
        }
        assertNotNull(carlaInscAtvAId);

        // Carla tries to confirm Atv A, but she has Atv B confirmed (overlapping). Should return 409 CONFLITO_DE_HORARIO
        HttpResponse<String> respConf = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/inscricoes/" + carlaInscAtvAId + "/confirmacao"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(409, respConf.statusCode());
        assertTrue(respConf.body().contains("CONFLITO_DE_HORARIO"));

        // Check that inscription is still 'convocada'
        HttpResponse<String> respGet = client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/inscricoes/" + carlaInscAtvAId))
                .header("X-Usuario", "p-carla")
                .GET().build(), HttpResponse.BodyHandlers.ofString());
        assertEquals("convocada", mapper.readValue(respGet.body(), Map.class).get("status"));
    }

    @Test
    public void confirmacao_com_prazo_vencido_retorna_422_convocacao_expirada() throws Exception {
        reset();
        setClock("2026-10-19T08:00:00-03:00");

        try (java.sql.Connection conn = Database.getConnection();
             java.sql.Statement stmt = conn.createStatement()) {
            stmt.execute("INSERT INTO atividades(id, titulo, tipo, salaId, vagas, cancelada) VALUES('atv_exp', 'Atv Exp', 'palestra', 'auditorio', 1, 0)");
            stmt.execute("INSERT INTO encontros(id, atividadeId, inicio, fim) VALUES('enc_exp', 'atv_exp', '2026-10-19T15:00:00-03:00', '2026-10-19T17:00:00-03:00')");
        }

        client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_exp/inscricoes"))
                .header("X-Usuario", "p-diego")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString());

        String carlaId = (String) mapper.readValue(client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/atividades/atv_exp/inscricoes"))
                .header("X-Usuario", "p-carla")
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(), HttpResponse.BodyHandlers.ofString()).body(), Map.class).get("id");

        // Diego cancels -> Carla is convoked at 08:00, valid until 10:00
        String diegoInscId = (String) mapper.readValue(client.send(HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/inscricoes?atividadeId=atv_exp"))
